package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.ClaimStore;
import net.officefloor.hq.app.claim.Lateness;
import net.officefloor.hq.app.claim.Rounding;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.rate.RateStore;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.SheetStore;
import org.springframework.stereotype.Service;

/**
 * Works out the sheet's figures as the screen shows them, and records in the audit file how a change
 * moved them: ROLLUP sheet=<id> by=<user> person=<name> claimed=<0.00> due-total=<0.00 or n/a> for each
 * person whose figures changed (a person new to the sheet counts as changed), in the order they were
 * added, then TOTALS sheet=<id> by=<user> claimed-total=<0.00> due-total=<0.00> when the sheet's totals
 * changed. A change that moves no figure records nothing here.
 */
@Service
public class RollupService {

    private static final String NA = "n/a";

    private final PersonStore people;
    private final ClaimStore claims;
    private final RateStore rates;
    private final SheetStore sheets;
    private final SettingStore settings;
    private final Audit audit;

    public RollupService(PersonStore people, ClaimStore claims, RateStore rates, SheetStore sheets, SettingStore settings,
            Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.settings = settings;
        this.audit = audit;
    }

    /** The sheet's figures as the store holds them now. */
    public Rollup snapshot(String sheetId) {
        LocalDate today = sheets.today(sheetId);
        List<Claim> all = claims.list(sheetId);
        BigDecimal floor = settings.floor(sheetId);
        Lateness lateness = new Lateness(settings.latePct(sheetId), sheets.today(sheetId),
                new Rounding(policyDate(sheetId), all));
        Map<Long, Rollup.Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
        for (Person person : people.list(sheetId)) {
            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
            BigDecimal due = BigDecimal.ZERO.setScale(2);
            boolean fixed = false;
            for (Claim claim : all) {
                if (claim.getPersonId() != person.getId()
                        || !counts(claim, person)) {
                    continue;
                }
                claimed = claimed.add(claim.getAmount());
                BigDecimal figure = lateness.due(claim, rates.find(sheetId, person.gradeOn(claim.getDate()), claim.getDate()), floor);
                if (figure != null) {
                    due = due.add(figure);
                }
                // A figure at a grade other than the one in force today does not hang on today's grade's rate.
                fixed |= claim.getSettledDue() != null || claim.isBound()
                        || (figure != null && !person.gradeOn(claim.getDate()).equals(person.gradeOn(today)));
            }
            boolean na = rates.find(sheetId, person.gradeOn(today), today) == null && !fixed;
            claimedTotal = claimedTotal.add(claimed);
            if (!na) {
                dueTotal = dueTotal.add(due);
            }
            figures.put(person.getId(), new Rollup.Figures(person.getName(), shown(claimed), na ? NA : shown(due)));
        }
        return new Rollup(figures, shown(claimedTotal), shown(dueTotal));
    }

    /** The due-total of the claims that count dated from..to (inclusive): the sum of their figures,
     *  skipping n/a, as the screen shows a period's due-total. */
    public BigDecimal dueBetween(String sheetId, LocalDate from, LocalDate to) {
        List<Claim> all = claims.list(sheetId);
        BigDecimal floor = settings.floor(sheetId);
        Lateness lateness = new Lateness(settings.latePct(sheetId), sheets.today(sheetId),
                new Rounding(policyDate(sheetId), all));
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (Person person : people.list(sheetId)) {
            for (Claim claim : all) {
                if (claim.getPersonId() != person.getId()
                        || !counts(claim, person)
                        || claim.getDate().isBefore(from) || claim.getDate().isAfter(to)) {
                    continue;
                }
                BigDecimal figure = lateness.due(claim, rates.find(sheetId, person.gradeOn(claim.getDate()), claim.getDate()), floor);
                if (figure != null) {
                    total = total.add(figure);
                }
            }
        }
        return total;
    }

    /** Records how the sheet's figures moved since {@code before}, the change made by {@code user}. */
    public void record(String sheetId, String user, Rollup before) {
        Rollup after = snapshot(sheetId);
        String who = " sheet=" + sheetId + " by=" + user;
        after.people().forEach((id, now) -> {
            if (!now.sameAs(before.people().get(id))) {
                audit.record("ROLLUP" + who + " person=" + now.name() + " claimed=" + now.claimed() + " due-total="
                        + now.dueTotal());
            }
        });
        if (!after.claimedTotal().equals(before.claimedTotal()) || !after.dueTotal().equals(before.dueTotal())) {
            audit.record("TOTALS" + who + " claimed-total=" + after.claimedTotal() + " due-total=" + after.dueTotal());
        }
    }

    /** The date the sheet's rounding turns on: the policy date set, else the sheet's today. */
    private LocalDate policyDate(String sheetId) {
        LocalDate policy = settings.policyDate(sheetId);
        return policy != null ? policy : sheets.today(sheetId);
    }

    /** Only OPEN, PENDING and SETTLED claims count, and a held person's OPEN or PENDING claims do not. */
    private static boolean counts(Claim claim, Person person) {
        return claim.getStatus() == ClaimStatus.SETTLED
                || (claim.getStatus().isOpen() && !person.isHeld());
    }

    private static String shown(BigDecimal value) {
        return value.setScale(2).toPlainString();
    }
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimFigure;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.ClaimStore;
import net.officefloor.hq.app.claim.Lateness;
import net.officefloor.hq.app.claim.Rounding;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.RateStore;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Takes a statement of the person on the sheet's today: their due-total (the sum of the figures of
 *  their claims that count; n/a when their grade in force today has no rate today and no counting claim
 *  keeps a fixed figure or a figure at another grade, the one in force on its date), binding each counting claim to its figure now (its floored live due when not fixed) and unbinding the rest. A settled
 *  claim keeps its fixed figure. The due-total includes the late charges of overdue claims, but a
 *  claim is bound to its figure without its charge, which keeps following the sheet's today. */
public class TakeStatement {
    public void take(@Val StatementRequest request, @Val Person person, ClaimStore claims, RateStore rates,
            SheetStore sheets, SettingStore settings, StatementStore statements, Out<Statement> statementOut) {
        String sheetId = person.getSheetId();
        LocalDate today = sheets.today(sheetId);
        BigDecimal floor = settings.floor(sheetId);
        Rounding rounding = Rounding.of(sheetId, settings, sheets, claims);
        Lateness lateness = new Lateness(settings.latePct(sheetId), today, rounding);
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean fixed = false;
        int counted = 0;
        // Locked, so a status change or another statement made at once waits for this one.
        for (Claim claim : claims.listForUpdate(sheetId, person.getId())) {
            // A held person's OPEN (or PENDING) claims count in no live total, so a statement neither counts nor binds them.
            boolean counts = claim.getStatus() == ClaimStatus.SETTLED
                    || (claim.getStatus().isOpen() && !person.isHeld());
            BigDecimal figure = null;
            if (counts) {
                figure = ClaimFigure.of(claim, rates.find(sheetId, person.gradeOn(claim.getDate()), claim.getDate()), floor, rounding);
                counted++;
                if (figure != null) {
                    total = total.add(claim.getSettledDue() != null ? figure : figure.add(lateness.charge(claim, figure)));
                }
                // A figure at a grade other than the one in force today does not hang on today's grade's rate.
                fixed |= claim.getSettledDue() != null || claim.isBound()
                        || (figure != null && !person.gradeOn(claim.getDate()).equals(person.gradeOn(today)));
            }
            claim.setStated(counts);
            claim.setStatedDue(figure);
            claims.bind(claim);
        }
        boolean na = rates.find(sheetId, person.gradeOn(today), today) == null && !fixed;
        Statement statement = new Statement(person.getId(), today, na ? null : total, counted);
        statements.add(sheetId, statement, request.user());
        statementOut.set(statement);
    }
}
package net.officefloor.hq.app.person;

import java.sql.PreparedStatement;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.NavigableMap;
import java.util.TreeMap;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The people kept per sheet, in the order they were added, each with their dated grades. */
@Repository
public class PersonStore {

    private final JdbcTemplate jdbc;

    public PersonStore(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The people's grades on the sheet (only the one person when {@code personId} is given), by person. */
    private Map<Long, NavigableMap<LocalDate, String>> grades(String sheetId, Long personId) {
        Map<Long, NavigableMap<LocalDate, String>> grades = new HashMap<>();
        jdbc.query("SELECT person_id, from_date, grade FROM person_grade WHERE sheet_id = ?"
                + (personId == null ? "" : " AND person_id = " + personId), rs -> {
                    grades.computeIfAbsent(rs.getLong("person_id"), k -> new TreeMap<>())
                            .put(rs.getObject("from_date", LocalDate.class), rs.getString("grade"));
                }, sheetId);
        return grades;
    }

    private List<Person> query(String sheetId, Long personId, String sql, Object... args) {
        Map<Long, NavigableMap<LocalDate, String>> grades = grades(sheetId, personId);
        RowMapper<Person> row = (rs, i) -> new Person(rs.getLong("id"), rs.getString("sheet_id"),
                rs.getString("name"), grades.getOrDefault(rs.getLong("id"), new TreeMap<>()), rs.getLong("version"),
                rs.getObject("retired_from", LocalDate.class), rs.getBoolean("held"));
        return jdbc.query(sql, row, args);
    }

    public List<Person> list(String sheetId) {
        return query(sheetId, null, "SELECT * FROM person WHERE sheet_id = ? ORDER BY id", sheetId);
    }

    public Person find(String sheetId, long id) {
        List<Person> found = query(sheetId, id, "SELECT * FROM person WHERE sheet_id = ? AND id = ?", sheetId, id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The person on the sheet with this name, ignoring case and the spaces around it; null when none. */
    public Person findByName(String sheetId, String name) {
        List<Person> found = query(sheetId, null, "SELECT * FROM person WHERE sheet_id = ? AND name_key = LOWER(?)",
                sheetId, name.trim());
        return found.isEmpty() ? null : found.get(0);
    }

    /** Whether another person on the sheet (not {@code exceptId}) has this name, ignoring case. */
    public boolean nameTaken(String sheetId, String name, Long exceptId) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND name_key = LOWER(?) AND id <> ?",
                Integer.class, sheetId, name.trim(), exceptId == null ? -1L : exceptId);
        return n != null && n > 0;
    }

    /** Adds the person with their first grade, which applies from the beginning of time. */
    public Person add(String sheetId, String name, String grade) {
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO person (sheet_id, name) VALUES (?, ?)", new String[] { "ID" });
            ps.setString(1, sheetId);
            ps.setString(2, name);
            return ps;
        }, keys);
        long id = keys.getKey().longValue();
        jdbc.update("INSERT INTO person_grade (sheet_id, person_id, from_date, grade) VALUES (?, ?, ?, ?)", sheetId,
                id, Person.START, grade);
        return new Person(id, sheetId, name, new TreeMap<>(Map.of(Person.START, grade)), 0);
    }

    /**
     * Stores the person over the version it was loaded at, moving the version on; false (nothing
     * stored) when someone else has stored another version since. The grade the edit records (if any)
     * is kept with the ones already recorded, replacing one from the same date.
     */
    public boolean save(Person person) {
        int n = jdbc.update(
                "UPDATE person SET name = ?, version = version + 1 WHERE sheet_id = ? AND id = ? AND version = ?",
                person.getName(), person.getSheetId(), person.getId(), person.getVersion());
        if (n == 1) {
            person.setVersion(person.getVersion() + 1);
            LocalDate from = person.getRecordFrom();
            if (from != null) {
                jdbc.update("MERGE INTO person_grade (sheet_id, person_id, from_date, grade) KEY (person_id, from_date)"
                        + " VALUES (?, ?, ?, ?)", person.getSheetId(), person.getId(), from, person.getGrades().get(from));
            }
        }
        return n == 1;
    }

